begin;
select no_plan();
create function pg_temp.ai_id(n integer) returns uuid language sql immutable as $$select ('af050000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table ev(k text primary key,v jsonb);grant all on ev to authenticated,service_role;
insert into ev values('old',jsonb_build_object('events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)));
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ai_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','runtime-'||n||'@test.invalid' from generate_series(1,3)n;
insert into public.profiles(id,role,name) select pg_temp.ai_id(n),case when n=2 then 'staff' else 'admin' end,'synthetic runtime' from generate_series(1,3)n on conflict(id) do update set role=excluded.role;
select ok(not(select issuance_enabled from dashboard_private.ai_agent_chat_support),'issuance defaults off');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role'])r cross join unnest(array['public.create_ai_agent_credential_v1(text,text[],jsonb,timestamptz)','public.list_ai_agent_credentials_v1(integer,integer)','public.revoke_ai_agent_credential_v1(uuid)'])f where has_function_privilege(r,f,'EXECUTE')),'old NEW-AI issuer bypasses revoked for all application roles');
select ok(has_function_privilege('authenticated','public.create_agent_credential_v1(text,text[],uuid[],timestamptz)','EXECUTE'),'legacy CLASS issuer ACL unchanged');
select ok(has_function_privilege('authenticated','public.ai_agent_credential_api_v1(text,jsonb)','EXECUTE') and not has_function_privilege('service_role','public.ai_agent_credential_api_v1(text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.ai_agent_credential_api_v1(text,jsonb)','EXECUTE'),'new wrapper authenticated only');
select ok(not has_function_privilege('authenticated','public.ai_agent_chat_configuration_api_v1(text,jsonb)','EXECUTE') and has_function_privilege('service_role','public.ai_agent_chat_configuration_api_v1(text,jsonb)','EXECUTE'),'config service only');
select ok(not has_function_privilege('authenticated','public.ai_agent_chat_bridge_grant_v1(text)','EXECUTE') and has_function_privilege('service_role','public.ai_agent_chat_bridge_grant_v1(text)','EXECUTE'),'bridge service only');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role'])r cross join unnest(array['dashboard_private.ai_agent_chat_support','dashboard_private.ai_agent_chat_configuration_receipts'])t where has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE')),'support and metadata receipt tables deny direct access');
create function pg_temp.create_input() returns jsonb language sql as $$select jsonb_build_object('label','synthetic runtime','scopes',array['ai-agent:requests:read','chat:send','chat:outbox:read'],'grant',jsonb_build_object('queues',array['employee_requests'],'actions',array['read'],'spaceKeys',array['space_1'],'purposes',array['bridge_reply','ai_completion'],'bridgeSourceId',pg_temp.ai_id(20)),'expiresAt',null,'idempotencyKey',pg_temp.ai_id(21))$$;
create function pg_temp.sync_input(revision text,enabled boolean,origin text) returns jsonb language sql as $$select jsonb_build_object('idempotencyKey',gen_random_uuid(),'revision',revision,'issuanceEnabled',enabled,'publicOrigin',origin,'spaces',(select jsonb_agg(jsonb_build_object('spaceKey','space_'||n,'resourceName',case when n=1 and origin is not null then 'spaces/RUNTIME' end)) from generate_series(1,7)n))$$;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);set local role authenticated;
select throws_ok($q$select public.create_ai_agent_credential_v1('x',array['ai-agent:requests:read'],'{}',null)$q$,'42501',null,'actual old issuer call denied');
select throws_ok($q$select public.list_ai_agent_credentials_v1(1,10)$q$,'42501',null,'actual old list call denied');
select throws_ok($q$select public.revoke_ai_agent_credential_v1(pg_temp.ai_id(4))$q$,'42501',null,'actual old revoke call denied');
select throws_ok($q$select public.ai_agent_credential_api_v1('create',pg_temp.create_input())$q$,'42501','ai_agent_support_disabled','new create denied when off');
select is(public.ai_agent_credential_api_v1('list','{}')->>'supportEnabled','false','list available off, safe support DTO');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('get','{}')$q$,'42501',null,'actual authenticated config call denied');reset role;
set local role service_role;
insert into ev values('initial',public.ai_agent_chat_configuration_api_v1('get','{}'));
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('1',true,null)-'issuanceEnabled')$q$,'22023','ai_agent_invalid','sync requires explicit issuance flag');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('1',true,'https://test.invalid/path'))$q$,'22023','ai_agent_invalid','origin cannot contain caller path');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('1',true,'https://test.invalid:65536'))$q$,'22023','ai_agent_invalid','canonical origin rejects out-of-range HTTPS port');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('1',true,'https://test.invalid:'||repeat('9',200)))$q$,'22023','ai_agent_invalid','oversized port returns validation SQLSTATE rather than integer overflow');
insert into ev values('syncinput',pg_temp.sync_input('1',true,'https://dashboard.test.invalid'));
insert into ev values('configured',public.ai_agent_chat_configuration_api_v1('sync',(select v from ev where k='syncinput')));
select is(public.ai_agent_chat_configuration_api_v1('sync',(select v from ev where k='syncinput')),(select v from ev where k='configured'),'sync exact replay historical snapshot');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('1',true,null))$q$,'55000','ai_agent_stale_version','sync stale snapshot CAS');
select throws_ok($q$select public.ai_agent_chat_configuration_api_v1('sync',(select v from ev where k='syncinput')||'{"issuanceEnabled":false}')$q$,'23514','ai_agent_idempotency_conflict','sync key binds exact payload');reset role;
set local role authenticated;
insert into ev values('first',public.ai_agent_credential_api_v1('create',pg_temp.create_input()));
insert into ev values('replay',public.ai_agent_credential_api_v1('create',pg_temp.create_input()));
select ok((select v->>'token' ~ '^tips_agent_[a-f0-9]{64}$' from ev where k='first'),'first raw token returned');
select ok((select v->'token'='null'::jsonb from ev where k='replay'),'replay raw token null');
select is((select v-'token' from ev where k='first'),(select v-'token' from ev where k='replay'),'replay preserves actual default expiry and metadata');
select throws_ok($q$select public.ai_agent_credential_api_v1('create',pg_temp.create_input()||'{"label":"changed"}')$q$,'23514','ai_agent_idempotency_conflict','create receipt payload conflict');reset role;
select is((select count(*) from dashboard_private.ai_agent_credentials where created_by=pg_temp.ai_id(1)),1::bigint,'identical create has one key');
select ok(not exists(select 1 from dashboard_private.ai_agent_request_receipts where operation='credential_create' and result::text like '%tips_agent_%'),'creation receipt has no raw token');
insert into ev values('spaceRevision',(select jsonb_build_object('revision',revision::text) from dashboard_private.chat_space_configuration where space_key='space_1'));
set local role service_role;
select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('2',false,'https://dashboard.test.invalid'));
select is(public.ai_agent_chat_configuration_api_v1('sync',(select v from ev where k='syncinput')),(select v from ev where k='configured'),'receipt remains historical after newer sync');reset role;
select is((select revision::text from dashboard_private.chat_space_configuration where space_key='space_1'),(select v->>'revision' from ev where k='spaceRevision'),'issuance-only toggle preserves Chat revision');
set local role authenticated;
select ok(public.ai_agent_credential_api_v1('create',pg_temp.create_input())->'token'='null'::jsonb,'exact create receipt recovery available support off');
select throws_ok($q$select public.ai_agent_credential_api_v1('create',pg_temp.create_input()||jsonb_build_object('idempotencyKey',gen_random_uuid()))$q$,'42501','ai_agent_support_disabled','fresh create off has no effect');reset role;
update public.profiles set role='staff' where id=pg_temp.ai_id(1);set local role authenticated;
select throws_ok($q$select public.ai_agent_credential_api_v1('create',pg_temp.create_input())$q$,'42501','ai_agent_forbidden','role loss denies replay before receipt');reset role;update public.profiles set role='admin' where id=pg_temp.ai_id(1);
create function pg_temp.hash() returns text language sql as $$select encode(sha256(convert_to((select v->>'token' from ev where k='first'),'UTF8')),'hex')$$;
set local role service_role;
select is(public.ai_agent_chat_bridge_grant_v1(pg_temp.hash())->>'bridgeSourceId',pg_temp.ai_id(20)::text,'stable source is server grant producer');
select throws_ok($q$select public.ai_agent_chat_bridge_grant_v1(repeat('0',64))$q$,'28000','ai_agent_unauthorized','unknown bridge credential denied');reset role;
select is((select rate_count from dashboard_private.ai_agent_credentials where id=(select (v->>'id')::uuid from ev where k='first')),0::bigint,'bridge getter consumes no quota');
update dashboard_private.chat_credential_space_grants set revoked_at=clock_timestamp() where credential_id=(select (v->>'id')::uuid from ev where k='first');set local role service_role;
select throws_ok($q$select public.ai_agent_chat_bridge_grant_v1(pg_temp.hash())$q$,'42501','ai_agent_grant_forbidden','bridge current grant loss rejected');reset role;update dashboard_private.chat_credential_space_grants set revoked_at=null;
-- Actual completion producer: immutable safe text, absolute link, no private content.
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body,status,result,notify_on_done,notification_space) values(pg_temp.ai_id(30),pg_temp.ai_id(1),E'<users/all> @everyone https://evil.invalid *title*\n'||U&'\202E','private body','done','private result',true,'space_1');
insert into dashboard_private.ai_agent_request_events(id,request_id,event_seq,kind,actor_kind,actor_id,requester_id,version) values(pg_temp.ai_id(31),pg_temp.ai_id(30),1,'done','user',pg_temp.ai_id(1),pg_temp.ai_id(1),1);
select dashboard_private.ai_agent_completion_outbox_v1(r,pg_temp.ai_id(31)) from dashboard_private.ai_agent_requests r where id=pg_temp.ai_id(30);
select ok((select payload->>'text' like '%https://dashboard.test.invalid/admin/ai-agent/%' and payload::text not like '%private%' and payload::text not like '%evil.invalid%' and payload::text not like '%@%' from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(30)),'completion producer safe absolute DTO');
select is(dashboard_private.ai_agent_chat_title_v1('<>@*[]'),'요청','empty sanitized title fallback');
set local role service_role;select public.ai_agent_chat_configuration_api_v1('sync',pg_temp.sync_input('3',false,'https://new.test.invalid'));reset role;
insert into ev values('budget',(select jsonb_build_object('count',count) from dashboard_private.chat_send_global_budget));
create function pg_temp.prepare() returns jsonb language sql as $$select public.ai_agent_chat_api_v1(pg_temp.hash(),'prepare_attempt',jsonb_build_object('id',(select id from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(30)),'revision','1','idempotencyKey',gen_random_uuid()))$$;
-- Function is invoker; resource lookup supplied before switching application role.
insert into ev values('prepareinput',(select jsonb_build_object('id',id,'revision','1','idempotencyKey',gen_random_uuid()) from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(30)));
set local role service_role;
select throws_ok($q$select public.ai_agent_chat_api_v1(pg_temp.hash(),'prepare_attempt',(select v from ev where k='prepareinput'))$q$,'55000','ai_agent_configuration_changed','current origin guard rejects immutable stale link');reset role;
select is((select count(*) from dashboard_private.chat_delivery_attempts),0::bigint,'origin conflict rolls back registered attempt');
select is((select count::text from dashboard_private.chat_send_global_budget),(select v->>'count' from ev where k='budget'),'origin conflict rolls back send budget');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);set local role authenticated;
select throws_ok($q$select public.ai_agent_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from ev where k='first'),'idempotencyKey',gen_random_uuid()))$q$,'P0002','ai_agent_not_found','foreign issuer revoke denied');reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);set local role authenticated;
select lives_ok($q$select public.ai_agent_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from ev where k='first'),'idempotencyKey',gen_random_uuid()))$q$,'revoke available while support off');reset role;
select is((select v from ev where k='old'),jsonb_build_object('events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)),'existing notification queues unchanged; provider zero');
select * from finish();rollback;
